1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"sort"
7		"strconv"
8		"strings"
9		"time"
10	)
11	
12	// 升级阶段标识。
13	const (
14		StageDownload = "download"
15		StageInstall  = "install"
16		StageRollback = "rollback"
17	)
18	
19	// 活动与设备在活动中的状态。
20	const (
21		CampaignRunning   = "running"
22		CampaignSucceeded = "succeeded"
23		CampaignFailed    = "failed"
24	
25		DevicePending     = "pending"     // 尚未领取下载
26		DeviceDownloading = "downloading" // 已领取下载，未完成
27		DeviceReady       = "ready"       // 下载成功，安装尚未领取
28		DeviceInstalling  = "installing"  // 已领取安装，未完成
29		DeviceSucceeded   = "succeeded"
30		DeviceFailed      = "failed"
31		DeviceTimeout     = "timeout"
32		DeviceSkipped     = "skipped" // 前序批次失败后，后续批次记为未执行
33	
34		// 回滚相关状态，仅出现在开启回滚的活动中。
35		DeviceAwaitingRollback  = "awaiting_rollback" // 安装失败已接受，等待领取回滚
36		DeviceRollingBack       = "rolling_back"      // 已领取回滚，未完成
37		DeviceRollbackSucceeded = "rollback_succeeded"
38		DeviceRollbackFailed    = "rollback_failed"
39		DeviceRollbackTimeout   = "rollback_timeout" // 到达截止时间时回滚仍未完成
40	)
41	
42	// VersionSpec 是一个已登记的升级目标版本及其允许的当前版本。
43	type VersionSpec struct {
44		// Target 是目标版本，与设备当前版本按字符串精确匹配。
45		Target string
46		// AllowedFrom 是允许升级到目标版本的当前版本列表。
47		AllowedFrom []string
48	}
49	
50	// versionState 是升级版本登记的内部状态。
51	type versionState struct {
52		Target      string
53		AllowedFrom []string
54	}
55	
56	// CampaignSpec 描述创建分批升级活动所需的全部信息。
57	type CampaignSpec struct {
58		// ID 是活动唯一标识，不能为空。
59		ID string
60		// Operator 是创建活动的操作者，不能为空。
61		Operator string
62		// CreatedAt 是活动创建时间。
63		CreatedAt time.Time
64		// TargetVersion 是已登记的目标版本。
65		TargetVersion string
66		// Devices 是按提交次序排列的有序设备列表，不能为空、不能重复。
67		Devices []string
68		// BatchSize 是批大小，必须是正整数。
69		BatchSize int
70		// WindowStart/WindowEnd 是维护窗口，开始时刻须早于结束时刻；
71		// 窗口包含开始时刻、不包含结束时刻。
72		WindowStart time.Time
73		WindowEnd   time.Time
74		// Deadline 是截止时间，必须晚于创建时间。
75		Deadline time.Time
76		// RollbackOnFailure 开启安装失败后的自动回滚，默认关闭。
77		// 关闭时安装失败即设备失败；开启后安装失败会先等待设备回滚到
78		// 首次领取下载时锁定的当前版本，活动最终仍为失败。
79		RollbackOnFailure bool
80	}
81	
82	// Operation 是派发给设备的一个升级操作。
83	type Operation struct {
84		// ID 是操作的稳定标识，重复查询未完成操作时保持不变，重开存储后仍有效。
85		ID         string
86		CampaignID string
87		DeviceID   string
88		// Kind 是 StageDownload、StageInstall 或 StageRollback。
89		Kind string
90		// TargetVersion 仅在回滚操作上有值，指明必须恢复到的锁定版本，
91		// 让设备明确知道要恢复哪个版本；下载与安装操作为空。
92		TargetVersion string
93	}
94	
95	// OperationResult 是设备提交的一次操作结果。
96	// 每次结果必须带活动、设备、操作标识及发生时间。
97	// 安装成功（Success 且操作是 install）时还须附带符合上报规则的设备上报：
98	// 正整数 Seq、等于目标版本的 Version 和完整 JSON 对象 Config。
99	// 回滚成功（Success 且操作是 rollback）时同样须附带上报，
100	// 但 Version 必须等于领取下载时锁定的回滚目标版本。
101	type OperationResult struct {
102		CampaignID  string
103		DeviceID    string
104		OperationID string
105		At          time.Time
106		Success     bool
107		// Reason 在失败时必填。
108		Reason string
109		// 安装成功时附带的设备上报。
110		Seq     uint64
111		Version string
112		Config  json.RawMessage
113	}
114	
115	// ResultRecord 是结果历史中的一条记录，按接受顺序保存。
116	type ResultRecord struct {
117		DeviceID    string
118		OperationID string
119		Stage       string
120		Success     bool
121		Reason      string
122		// Version 为安装或回滚成功时上报的版本，其余为空。
123		Version string
124		At      time.Time
125	}
126	
127	// opState 是单个设备单个阶段的操作与结果状态。
128	type opState struct {
129		ID string
130		// Claimed 表示操作是否已被领取；未领取的操作不能提交结果。
131		Claimed   bool
132		ClaimedAt time.Time
133		// 已接受的结果。
134		HasResult     bool
135		Success       bool
136		Reason        string
137		At            time.Time
138		ResultSeq     uint64
139		ResultVersion string
140		ResultConfig  json.RawMessage
141	}
142	
143	// campaignDevice 是单台设备在一个活动中的完整状态。
144	type campaignDevice struct {
145		DeviceID string
146		Batch    int
147		Download opState
148		Install  opState
149		// Rollback 是安装失败后的回滚操作，仅在开启回滚的活动中使用。
150		Rollback opState
151		// RollbackTarget 是首次领取下载时锁定的设备当前版本，回滚必须恢复到它。
152		// 后续普通上报不改变它，也不要求它另行登记为升级目标。
153		RollbackTarget string
154		// Status/Phase/Reason/At 描述设备当前状态；
155		// failed 必须记录阶段、原因和时间；timeout/skipped 同理。
156		Status string
157		Phase  string
158		Reason string
159		At     time.Time
160	}
161	
162	// campaignState 是一个分批升级活动的内部状态。
163	type campaignState struct {
164		ID          string
165		Operator    string
166		Target      string
167		CreatedAt   time.Time
168		BatchSize   int
169		WindowStart time.Time
170		WindowEnd   time.Time
171		Deadline    time.Time
172		// RollbackOnFailure 表示安装失败后是否进入回滚；旧存储缺省为关闭。
173		RollbackOnFailure bool
174		Devices           []*campaignDevice
175		index             map[string]int
176		Results           []ResultRecord
177		// idScheme 是操作标识方案（opIDScheme*），随活动持久化；
178		// 修复前保存的活动为 opIDSchemeLegacy，新活动为 opIDSchemeV2。
179		idScheme int
180		// LastTime 是本活动已接受的最晚时间，用于拒绝时间倒退。
181		LastTime time.Time
182		Status   string
183		Ended    bool
184		EndedAt  time.Time
185	}
186	
187	// RegisterUpgrade 登记一个升级目标版本及允许升级的当前版本列表。
188	// 版本字符串精确匹配；列表不能为空、不能含空串、不能包含目标版本。
189	// 目标版本重复登记时返回 ErrVersionExists 并保留原记录。
190	func (s *Store) RegisterUpgrade(targetVersion string, allowedFrom []string) error {
191		s.mu.Lock()
192		defer s.mu.Unlock()
193		if err := s.checkOpen(); err != nil {
194			return err
195		}
196		if targetVersion == "" {
197			return ErrInvalidVersion
198		}
199		if err := validateAllowedFrom(targetVersion, allowedFrom); err != nil {
200			return err
201		}
202		if _, ok := s.versions[targetVersion]; ok {
203			return fmt.Errorf("%w: %s", ErrVersionExists, targetVersion)
204		}
205		from := append([]string(nil), allowedFrom...)
206		return s.commit(func() error {
207			s.versions[targetVersion] = &versionState{Target: targetVersion, AllowedFrom: from}
208			return nil
209		})
210	}
211	
212	func validateAllowedFrom(target string, allowedFrom []string) error {
213		if len(allowedFrom) == 0 {
214			return fmt.Errorf("%w: list is empty", ErrInvalidVersionList)
215		}
216		for _, v := range allowedFrom {
217			if v == "" {
218				return fmt.Errorf("%w: contains empty version", ErrInvalidVersionList)
219			}
220			if v == target {
221				return fmt.Errorf("%w: contains target version %s", ErrInvalidVersionList, target)
222			}
223		}
224		return nil
225	}
226	
227	// CreateCampaign 创建分批升级活动。任何必填信息缺失、设备或目标版本未登记、
228	// 设备当前版本不兼容或设备已参加未结束活动时，整次创建失败，不留下部分记录。
229	func (s *Store) CreateCampaign(spec CampaignSpec) error {
230		s.mu.Lock()
231		defer s.mu.Unlock()
232		if err := s.checkOpen(); err != nil {
233			return err
234		}
235		// 先做全部校验，全部通过后才写入，保证原子创建。
236		if spec.ID == "" {
237			return ErrInvalidCampaignID
238		}
239		if spec.Operator == "" {
240			return ErrInvalidOperator
241		}
242		if spec.CreatedAt.IsZero() {
243			return fmt.Errorf("%w: created at", ErrInvalidTime)
244		}
245		if spec.WindowStart.IsZero() || spec.WindowEnd.IsZero() {
246			return fmt.Errorf("%w: maintenance window", ErrInvalidTime)
247		}
248		if spec.Deadline.IsZero() {
249			return fmt.Errorf("%w: deadline", ErrInvalidTime)
250		}
251		if len(spec.Devices) == 0 {
252			return ErrInvalidDeviceList
253		}
254		seen := make(map[string]bool, len(spec.Devices))
255		for _, id := range spec.Devices {
256			if id == "" {
257				return ErrInvalidDeviceID
258			}
259			if seen[id] {
260				return fmt.Errorf("%w: %s", ErrDuplicateDevice, id)
261			}
262			seen[id] = true
263		}
264		if spec.BatchSize <= 0 {
265			return ErrInvalidBatchSize
266		}
267		if !spec.WindowStart.Before(spec.WindowEnd) {
268			return ErrInvalidWindow
269		}
270		if !spec.Deadline.After(spec.CreatedAt) {
271			return ErrInvalidDeadline
272		}
273		if spec.TargetVersion == "" {
274			return ErrInvalidVersion
275		}
276		if _, ok := s.versions[spec.TargetVersion]; !ok {
277			return fmt.Errorf("%w: %s", ErrVersionNotFound, spec.TargetVersion)
278		}
279		if _, ok := s.campaigns[spec.ID]; ok {
280			return fmt.Errorf("%w: %s", ErrCampaignExists, spec.ID)
281		}
282		ver := s.versions[spec.TargetVersion]
283		// 新标识不能与存储内其他操作的标识相同，同一设备不同阶段也不共用：
284		// v2 编码本身按（活动, 设备, 阶段）区分，nonce 再避开与旧方案标识的偶然相同。
285		taken := s.takenOperationIDs()
286		newOpID := func(deviceID, stage string) string {
287			for nonce := 0; ; nonce++ {
288				id := encodeOperationIDV2(nonce, spec.ID, deviceID, stage)
289				if !taken[id] {
290					taken[id] = true
291					return id
292				}
293			}
294		}
295		devs := make([]*campaignDevice, 0, len(spec.Devices))
296		for i, id := range spec.Devices {
297			d, ok := s.devices[id]
298			if !ok {
299				return fmt.Errorf("%w: %s", ErrDeviceNotFound, id)
300			}
301			if !containsString(ver.AllowedFrom, d.Version) {
302				return fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, id, d.Version)
303			}
304			if s.deviceBusy(id, spec.ID) {
305				return fmt.Errorf("%w: %s", ErrDeviceBusy, id)
306			}
307			devs = append(devs, &campaignDevice{
308				DeviceID: id,
309				Batch:    i / spec.BatchSize,
310				Status:   DevicePending,
311				Phase:    StageDownload,
312				Download: opState{ID: newOpID(id, StageDownload)},
313				Install:  opState{ID: newOpID(id, StageInstall)},
314				Rollback: opState{ID: newOpID(id, StageRollback)},
315			})
316		}
317		campaign := &campaignState{
318			ID:                spec.ID,
319			Operator:          spec.Operator,
320			Target:            spec.TargetVersion,
321			CreatedAt:         spec.CreatedAt,
322			BatchSize:         spec.BatchSize,
323			WindowStart:       spec.WindowStart,
324			WindowEnd:         spec.WindowEnd,
325			Deadline:          spec.Deadline,
326			RollbackOnFailure: spec.RollbackOnFailure,
327			Devices:           devs,
328			index:             make(map[string]int, len(devs)),
329			idScheme:          opIDSchemeV2,
330			LastTime:          spec.CreatedAt,
331			Status:            CampaignRunning,
332		}
333		for i, cd := range devs {
334			campaign.index[cd.DeviceID] = i
335		}
336		return s.commit(func() error {
337			s.campaigns[spec.ID] = campaign
338			return nil
339		})
340	}
341	
342	// deviceBusy 判断设备是否已参加另一个尚未结束的活动。
343	func (s *Store) deviceBusy(deviceID, excludeCampaign string) bool {
344		for id, c := range s.campaigns {
345			if id == excludeCampaign || c.Ended {
346				continue
347			}
348			if _, ok := c.index[deviceID]; ok {
349				return true
350			}
351		}
352		return false
353	}
354	
355	// operationID 是修复前的旧标识方案：冒号拼接。活动或设备标识含冒号时，
356	// 不同（活动, 设备）组合会拼出相同标识，仅用于兼容校验修复前保存的活动；
357	// 新活动一律使用 encodeOperationIDV2。
358	func operationID(campaignID, deviceID, stage string) string {
359		return campaignID + ":" + deviceID + ":" + stage
360	}
361	
362	// 操作标识方案编号，随活动一起持久化；缺省（旧存储）为旧方案。
363	const (
364		opIDSchemeLegacy = 0
365		opIDSchemeV2     = 1
366	)
367	
368	const opIDV2Prefix = "v2:"
369	
370	// encodeOperationIDV2 生成无歧义的操作标识：活动与设备标识用长度前缀编码，
371	// 任何非空标识（含冒号、中文等）都按原字符串精确保留，（活动, 设备, 阶段）
372	// 三元组与标识一一对应。nonce 用于避开与存储内已有标识（如旧方案标识）
373	// 偶然相同的情形。
374	func encodeOperationIDV2(nonce int, campaignID, deviceID, stage string) string {
375		return fmt.Sprintf("v2:%d:%d:%s%d:%s%s",
376			nonce, len(campaignID), campaignID, len(deviceID), deviceID, stage)
377	}
378	
379	// parseOperationIDV2 解析 v2 操作标识，还原活动、设备与阶段。
380	// 只接受规范编码（解析后原样重编码必须等于入参）。
381	func parseOperationIDV2(id string) (campaignID, deviceID, stage string, ok bool) {
382		rest, found := strings.CutPrefix(id, opIDV2Prefix)
383		if !found {
384			return "", "", "", false
385		}
386		readInt := func() (int, bool) {
387			i := strings.IndexByte(rest, ':')
388			if i <= 0 {
389				return 0, false
390			}
391			n, err := strconv.Atoi(rest[:i])
392			if err != nil || n < 0 {
393				return 0, false
394			}
395			rest = rest[i+1:]
396			return n, true
397		}
398		readStr := func(n int) (string, bool) {
399			if n <= 0 || len(rest) < n {
400				return "", false
401			}
402			s := rest[:n]
403			rest = rest[n:]
404			return s, true
405		}
406		nonce, ok1 := readInt()
407		lenC, ok2 := readInt()
408		if !ok1 || !ok2 {
409			return "", "", "", false
410		}
411		campaignID, ok1 = readStr(lenC)
412		lenD, ok2 := readInt()
413		if !ok1 || !ok2 {
414			return "", "", "", false
415		}
416		deviceID, ok1 = readStr(lenD)
417		if !ok1 {
418			return "", "", "", false
419		}
420		stage = rest
421		if !validStage(stage) || encodeOperationIDV2(nonce, campaignID, deviceID, stage) != id {
422			return "", "", "", false
423		}
424		return campaignID, deviceID, stage, true
425	}
426	
427	func validStage(stage string) bool {
428		return stage == StageDownload || stage == StageInstall || stage == StageRollback
429	}
