1156	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
1157	// 失败或超时原因及结果历史。返回数据为独立副本。
1158	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
1159		s.mu.Lock()
1160		defer s.mu.Unlock()
1161		if err := s.checkOpen(); err != nil {
1162			return CampaignView{}, err
1163		}
1164		c, err := s.lookupCampaign(campaignID)
1165		if err != nil {
1166			return CampaignView{}, err
1167		}
1168		v := CampaignView{
1169			ID:                c.ID,
1170			Operator:          c.Operator,
1171			TargetVersion:     c.Target,
1172			CreatedAt:         c.CreatedAt,
1173			BatchSize:         c.BatchSize,
1174			WindowStart:       c.WindowStart,
1175			WindowEnd:         c.WindowEnd,
1176			Deadline:          c.Deadline,
1177			RollbackOnFailure: c.RollbackOnFailure,
1178			Status:            c.Status,
1179			Ended:             c.Ended,
1180			EndedAt:           c.EndedAt,
1181			Results:           make([]ResultRecord, len(c.Results)),
1182		}
1183		copy(v.Results, c.Results)
1184		for _, cd := range c.Devices {
1185			dv := DeviceStatusView{
1186				DeviceID:       cd.DeviceID,
1187				Batch:          cd.Batch,
1188				Status:         cd.Status,
1189				Phase:          cd.Phase,
1190				Reason:         cd.Reason,
1191				At:             cd.At,
1192				DownloadID:     cd.Download.ID,
1193				InstallID:      cd.Install.ID,
1194				RollbackID:     cd.Rollback.ID,
1195				RollbackTarget: cd.RollbackTarget,
1196			}
1197			// 安装失败原因与时间独立保留，进入回滚后也不被回滚结果覆盖。
1198			if cd.Install.HasResult && !cd.Install.Success {
1199				dv.InstallFailReason = cd.Install.Reason
1200				dv.InstallFailAt = cd.Install.At
1201			}
1202			// 回滚结果的原因与时间单独呈现。
1203			if cd.Rollback.HasResult {
1204				dv.RollbackResult = true
1205				dv.RollbackSuccess = cd.Rollback.Success
1206				dv.RollbackReason = cd.Rollback.Reason
1207				dv.RollbackAt = cd.Rollback.At
1208			}
1209			v.Devices = append(v.Devices, dv)
1210			for len(v.Batches) <= cd.Batch {
1211				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
1212			}
1213			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
1214		}
1215		return v, nil
1216	}
