1232	// GetDeviceWork 查询设备当前版本及其待执行操作。
1233	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
1234		s.mu.Lock()
1235		defer s.mu.Unlock()
1236		if err := s.checkOpen(); err != nil {
1237			return DeviceWork{}, err
1238		}
1239		d, err := s.lookup(deviceID)
1240		if err != nil {
1241			return DeviceWork{}, err
1242		}
1243		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
1244		for id, c := range s.campaigns {
1245			if c.Ended {
1246				continue
1247			}
1248			i, ok := c.index[deviceID]
1249			if !ok {
1250				continue
1251			}
1252			cd := c.Devices[i]
1253			// 设备已结束自己的步骤但活动尚未结束时，仍保留活动标识、不再有待办；
1254			// pendingStage 是待办判定的唯一来源，stageOperation 是描述的唯一来源，
1255			// 因而这里看到的标识/目标与 Claim 实际领取到的操作完全一致。
1256			if stage, claimed := pendingStage(cd); stage != "" {
1257				w.Pending = stageOperation(c, cd, stage)
1258				w.PendingClaimed = claimed
1259			}
1260			w.CampaignID = id
1261			break
1262		}
1263		return w, nil
1264	}
1265	
1266	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
1267	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
1268		s.mu.Lock()
1269		defer s.mu.Unlock()
1270		if err := s.checkOpen(); err != nil {
1271			return nil, err
1272		}
1273		out := make([]VersionSpec, 0, len(s.versions))
1274		for _, v := range s.versions {
1275			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
1276		}
1277		sort.Slice(out, func(i, j int) bool { return out[i].Target < out[j].Target })
1278		return out, nil
1279	}
1280

