812			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
813			DeviceAwaitingRollback, DeviceRollingBack,
814			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
815			return true
816		default:
