241		// 缺少本设备的下载成功结果，即使设备当前版本已被普通上报改成目标版本，
242		// 也不能替代下载结果打开存储。
243		t.Run("ready without download even if version already target", func(t *testing.T) {
244			s, spec := buildReadyOpen(t)
245			// 普通上报把当前版本改成目标版本 v2：只改影子，不推进活动。
246			if err := s.Report("d1", 2, upBase.Add(2*time.Minute), "v2", json.RawMessage(`{}`)); err != nil {
247				t.Fatal(err)
248			}
249			dir := closeStore(t, s)
250			mutateDeviceOp(t, dir, spec.ID, "d1", "download", func(o map[string]any) {
251				o["hasResult"] = false
252				o["success"] = false
253			})
254			dropDeviceStageHistory(t, dir, spec.ID, "d1", StageDownload)
255			original := readStoreBytesForTest(t, dir)
256			assertReopenCorrupt(t, dir, original)
257		})
258	
259		// ---- installing（正在安装）的矛盾记录 --------------------------------
260	
261		// 安装尚未领取却保存为 installing（其余记录自洽）。
262		t.Run("installing without install claim", func(t *testing.T) {
263			_, dir, spec := setupInstalling(t)
264			original := mutateDeviceOp(t, dir, spec.ID, "d1", "install", func(o map[string]any) {
265				o["claimed"] = false
266				delete(o, "claimedAt")
267			})
268			assertReopenCorrupt(t, dir, original)
269		})
270	
271		// 已接受安装成功结果（配套历史、附带上报与设备影子自洽）却仍保存为
272		// installing：有了结果就不再是“正在安装”。
273		t.Run("installing with install success result", func(t *testing.T) {
274			s, spec, _ := buildInstallingOpen(t)
275			if err := s.Report("d1", 2, upBase.Add(3*time.Minute), "v2", json.RawMessage(`{}`)); err != nil {
276				t.Fatal(err)
277			}
278			dir := closeStore(t, s)
279			mutateDeviceOp(t, dir, spec.ID, "d1", "install", func(o map[string]any) {
280				o["hasResult"] = true
281				o["success"] = true
282				o["at"] = "2026-10-02T12:03:00Z"
283				o["resultSeq"] = 2.0
284				o["resultVersion"] = "v2"
285				o["resultConfig"] = map[string]any{}
286			})
287			appendInstallHistory(t, dir, spec.ID, installHistoryRec(spec, true, "2026-10-02T12:03:00Z"))
288			setCampaignLastTime(t, dir, spec.ID, "2026-10-02T12:04:00Z")
289			original := readStoreBytesForTest(t, dir)
290			assertReopenCorrupt(t, dir, original)
291		})
292	
293		// 已接受安装失败结果（配套失败历史自洽）也不能继续使用 installing。
294		t.Run("installing with install failure result", func(t *testing.T) {
295			s, spec, _ := buildInstallingOpen(t)
296			dir := closeStore(t, s)
297			mutateDeviceOp(t, dir, spec.ID, "d1", "install", func(o map[string]any) {
298				o["hasResult"] = true
299				o["success"] = false
300				o["reason"] = "install boom"
301				o["at"] = "2026-10-02T12:03:00Z"
302			})
303			appendInstallHistory(t, dir, spec.ID, installHistoryRec(spec, false, "2026-10-02T12:03:00Z"))
304			setCampaignLastTime(t, dir, spec.ID, "2026-10-02T12:04:00Z")
305			original := readStoreBytesForTest(t, dir)
306			assertReopenCorrupt(t, dir, original)
307		})
308	
309		// installing 也必须停留在安装阶段。
310		t.Run("installing with download phase", func(t *testing.T) {
311			_, dir, spec := setupInstalling(t)
312			original := setDeviceStatusPhase(t, dir, spec.ID, "d1", DeviceInstalling, StageDownload)
313			assertReopenCorrupt(t, dir, original)
314		})
315	
316		// installing 同样必须有本设备自己接受的下载成功结果。
317		t.Run("installing without own download success", func(t *testing.T) {
318			_, dir, spec := setupInstalling(t)
319			mutateDeviceOp(t, dir, spec.ID, "d1", "download", func(o map[string]any) {
320				o["hasResult"] = false
321				o["success"] = false
322			})
323			dropDeviceStageHistory(t, dir, spec.ID, "d1", StageDownload)
324			original := readStoreBytesForTest(t, dir)
