326		})
327	}
328	
329	// TestRestoreUnfinishedInstallResumes 保护正常的未完成安装在重开后仍能恢复使用：
330	// 等待安装的设备保留原安装待办及未领取标记；已领取安装的设备保留原操作标识和
331	// 已领取标记，后续仍能按现有规则提交结果。设备离线、维护窗口已经结束或普通上报
332	// 改变当前版本，都不能单凭这些情况认定进度损坏，也不能自动补上安装结果。
333	func TestRestoreUnfinishedInstallResumes(t *testing.T) {
334		// ready：设备离线、维护窗口已结束后重开，仍保留未领取的安装待办；
335		// 窗口外领取仍返回空操作，不补造任何结果。
336		t.Run("ready survives offline and ended window", func(t *testing.T) {
337			s, spec := buildReadyOpen(t)
338			// 离线并把时间推进到维护窗口结束之后、截止之前。
339			if err := s.SetOffline("d1"); err != nil {
