341			}
342			if err := s.AdvanceCampaign(spec.ID, upBase.Add(90*time.Minute)); err != nil {
343				t.Fatal(err)
344			}
345			wantWork, err := s.GetDeviceWork("d1")
346			if err != nil {
347				t.Fatal(err)
348			}
349			dir := closeStore(t, s)
350	
351			s2, err := Open(dir)
352			if err != nil {
353				t.Fatalf("ready device offline past window must reopen: %v", err)
354			}
355			defer s2.Close()
356	
357			cv := mustGetCampaign(s2, spec.ID)
358			if cv.Ended || findDevice(cv, "d1").Status != DeviceReady ||
359				findDevice(cv, "d1").Phase != StageInstall {
360				t.Fatalf("ready progress must be preserved: %+v", cv)
361			}
362			if len(cv.Results) != 1 || cv.Results[0].Stage != StageDownload {
363				t.Fatalf("no install result may be fabricated: %+v", cv.Results)
364			}
365			w, err := s2.GetDeviceWork("d1")
366			if err != nil {
367				t.Fatal(err)
368			}
369			if w.CampaignID != spec.ID || w.Pending == nil ||
370				w.Pending.Kind != StageInstall || w.PendingClaimed ||
371				w.Pending.ID != wantWork.Pending.ID {
372				t.Fatalf("unclaimed install todo lost: %+v want %+v", w, wantWork)
373			}
374			// 窗口已结束：即使重新上线，未领取的安装仍领不到（正常等待，不是错误），
375			// 状态与待办保持不变。
376			bringOnline(t, s2, "d1")
377			op, err := s2.Claim(spec.ID, "d1", upBase.Add(91*time.Minute))
378			if err != nil {
379				t.Fatalf("claim outside window must be a no-op, not error: %v", err)
380			}
381			if op != nil {
382				t.Fatalf("unclaimed install must not be dispatched past window: %+v", op)
383			}
384			w2, _ := s2.GetDeviceWork("d1")
385			if w2.Pending == nil || w2.PendingClaimed || w2.Pending.ID != w.Pending.ID {
386				t.Fatalf("pending install changed after out-of-window claim: %+v", w2)
387			}
388			if findDevice(mustGetCampaign(s2, spec.ID), "d1").Status != DeviceReady {
389				t.Fatalf("ready status must remain after out-of-window claim")
390			}
391		})
392	
393		// ready 原样重开（在线、窗口内）：未领取标记与操作标识保留，
394		// 领取后可按现有规则提交安装成功，活动正常成功结束。
395		t.Run("ready reopens and completes", func(t *testing.T) {
396			s, spec := buildReadyOpen(t)
397			wantWork, _ := s.GetDeviceWork("d1")
398			dir := closeStore(t, s)
399	
400			s2, err := Open(dir)
401			if err != nil {
402				t.Fatalf("ready store must reopen: %v", err)
403			}
404			defer s2.Close()
405			w, err := s2.GetDeviceWork("d1")
406			if err != nil {
407				t.Fatal(err)
408			}
409			if w.Pending == nil || w.Pending.Kind != StageInstall || w.PendingClaimed ||
410				w.Pending.ID != wantWork.Pending.ID {
411				t.Fatalf("pending install not restored: %+v want %+v", w, wantWork)
412			}
413			in, err := s2.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
414			if err != nil || in == nil || in.Kind != StageInstall || in.ID != wantWork.Pending.ID {
415				t.Fatalf("claim restored install: %v %+v", err, in)
416			}
417			if err := s2.SubmitResult(OperationResult{
418				CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
419				At: upBase.Add(3 * time.Minute), Success: true,
420				Seq: 2, Version: "v2", Config: json.RawMessage(`{}`),
421			}); err != nil {
422				t.Fatalf("submit install after reopen: %v", err)
423			}
424			cv := mustGetCampaign(s2, spec.ID)
425			if !cv.Ended || cv.Status != CampaignSucceeded ||
426				findDevice(cv, "d1").Status != DeviceSucceeded {
427				t.Fatalf("campaign should succeed after resumed install: %+v", cv)
428			}
429		})
430	
431		// installing：原操作标识与已领取标记保留；领取后的普通上报改变了影子，
432		// 重开后仍能用原标识按现有规则提交安装成功（已领取操作可在窗口外提交）。
433		t.Run("installing reopens and submits result after plain report", func(t *testing.T) {
434			s, spec, in := buildInstallingOpen(t)
435			// 领取安装后来了一次普通上报：只改影子，不替代安装结果、不清待办。
436			if err := s.Report("d1", 2, upBase.Add(3*time.Minute), "v1", json.RawMessage(`{"x":1}`)); err != nil {
437				t.Fatal(err)
438			}
439			wantWork, _ := s.GetDeviceWork("d1")
440			dir := closeStore(t, s)
441	
442			s2, err := Open(dir)
443			if err != nil {
444				t.Fatalf("installing store must reopen: %v", err)
445			}
446			defer s2.Close()
447			cv := mustGetCampaign(s2, spec.ID)
448			if cv.Ended || findDevice(cv, "d1").Status != DeviceInstalling ||
449				findDevice(cv, "d1").Phase != StageInstall {
450				t.Fatalf("installing progress must be preserved: %+v", cv)
451			}
452			if len(cv.Results) != 1 {
453				t.Fatalf("no install result may be fabricated: %+v", cv.Results)
454			}
455			w, err := s2.GetDeviceWork("d1")
456			if err != nil {
457				t.Fatal(err)
458			}
459			if w.Pending == nil || w.Pending.Kind != StageInstall || !w.PendingClaimed ||
460				w.Pending.ID != in.ID || w.Pending.ID != wantWork.Pending.ID {
461				t.Fatalf("claimed install not restored: %+v want %+v", w, wantWork)
462			}
463			// 已领取操作可在窗口外、截止前提交结果：沿用原标识与现有序号规则。
464			if err := s2.SubmitResult(OperationResult{
465				CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
466				At: upBase.Add(75 * time.Minute), Success: true,
467				Seq: 3, Version: "v2", Config: json.RawMessage(`{}`),
468			}); err != nil {
469				t.Fatalf("submit install result after reopen: %v", err)
470			}
471			view, _ := s2.Get("d1")
472			if view.Version != "v2" || view.LastSeq != 3 {
473				t.Fatalf("shadow not updated by resumed install success: %+v", view)
474			}
475			if cv2 := mustGetCampaign(s2, spec.ID); !cv2.Ended || cv2.Status != CampaignSucceeded {
476				t.Fatalf("campaign should succeed: %+v", cv2)
477			}
478		})
479	
480		// 已领取安装的设备离线重开：离线不影响已领取待办的恢复。
481		t.Run("installing reopens while offline", func(t *testing.T) {
482			s, spec, in := buildInstallingOpen(t)
483			if err := s.SetOffline("d1"); err != nil {
484				t.Fatal(err)
485			}
486			dir := closeStore(t, s)
487			s2, err := Open(dir)
488			if err != nil {
489				t.Fatalf("offline installing store must reopen: %v", err)
490			}
491			defer s2.Close()
492			if sh, _ := s2.Get("d1"); sh.Online {
493				t.Fatalf("offline state must be preserved")
494			}
495			w, err := s2.GetDeviceWork("d1")
496			if err != nil {
497				t.Fatal(err)
498			}
499			if w.Pending == nil || w.Pending.Kind != StageInstall || !w.PendingClaimed ||
500				w.Pending.ID != in.ID {
501				t.Fatalf("claimed install todo lost while offline: %+v", w)
502			}
503			if findDevice(mustGetCampaign(s2, spec.ID), "d1").Status != DeviceInstalling {
504				t.Fatalf("installing status lost")
505			}
506		})
507	
508		// 尚未领取安装没有安装领取时间、尚无安装结果没有结果时间：正常缺省记录
509		// 必须原样打开，Open 不得改写文件补这些时间。
510		t.Run("missing claim and result times are normal", func(t *testing.T) {
511			_, dir, spec := setupReady(t)
512			path := filepath.Join(dir, storeFileName)
513			data, err := os.ReadFile(path)
514			if err != nil {
515				t.Fatal(err)
516			}
517			s2, err := Open(dir)
518			if err != nil {
519				t.Fatalf("ready store with default install times must reopen: %v", err)
520			}
521			if findDevice(mustGetCampaign(s2, spec.ID), "d1").Status != DeviceReady {
522				t.Fatalf("ready status lost")
523			}
524			s2.Close()
525			data2, err := os.ReadFile(path)
526			if err != nil {
527				t.Fatal(err)
528			}
529			if string(data2) != string(data) {
530				t.Fatalf("open must not fabricate missing times")
531			}
532		})
533	}
