12	// 以下结构仅用于在测试中拼装存储文件，字段与磁盘格式对应。
13	type fixAudit struct {
14		Operator  string          `json:"operator"`
15		Time      string          `json:"time"`
16		Revision  uint64          `json:"revision"`
17		RequestID string          `json:"requestId,omitempty"`
18		Before    json.RawMessage `json:"before"`
19		After     json.RawMessage `json:"after"`
20	}
21	
22	type fixState struct {
23		Version        string            `json:"version"`
24		Online         bool              `json:"online"`
25		Revision       uint64            `json:"revision"`
26		Desired        any               `json:"desired"`
27		Reported       any               `json:"reported"`
28		LastSeq        uint64            `json:"lastSeq,omitempty"`
29		LastReportTime string            `json:"lastReportTime,omitempty"`
30		DiffSince      map[string]string `json:"diffSince,omitempty"`
31		Audit          []fixAudit        `json:"audit,omitempty"`
32	}
33	
34	type fixStore struct {
35		Format  int                 `json:"format"`
36		Devices map[string]fixState `json:"devices"`
37	}
38	
39	// writeFixStore 写入一份拼装存储，返回目录与写入的原始字节。
40	func writeFixStore(t *testing.T, doc fixStore) (string, []byte) {
41		t.Helper()
42		data, err := json.Marshal(doc)
43		if err != nil {
44			t.Fatal(err)
45		}
46		dir := t.TempDir()
47		if err := os.WriteFile(filepath.Join(dir, storeFileName), data, 0o644); err != nil {
48			t.Fatal(err)
49		}
50		return dir, data
51	}
52	
53	func twoAuditDoc() fixStore {
54		return fixStore{Format: 1, Devices: map[string]fixState{
55			"dev-1": {
56				Version:   "1.0",
57				Revision:  2,
58				Desired:   json.RawMessage(`{"a":2}`),
59				Reported:  json.RawMessage(`{}`),
60				DiffSince: map[string]string{"/a": "2026-10-02T12:00:00Z"},
61				Audit: []fixAudit{
62					{Operator: "alice", Time: "2026-10-02T12:00:00Z", Revision: 1, Before: json.RawMessage(`{}`), After: json.RawMessage(`{"a":1}`)},
63					{Operator: "bob", Time: "2026-10-02T12:01:00Z", Revision: 2, Before: json.RawMessage(`{"a":1}`), After: json.RawMessage(`{"a":2}`)},
64				},
65			},
66		}}
67	}
68	
69	// 正常的两次修改历史：修订号 1、2 衔接，末条修改后等于当前期望配置。
70	func TestRestoreAuditChainAccepted(t *testing.T) {
71		dir, _ := writeFixStore(t, twoAuditDoc())
72		s, err := Open(dir)
