74			t.Fatalf("valid audit chain must open: %v", err)
75		}
76		defer s.Close()
77		v, err := s.Get("dev-1")
78		if err != nil {
79			t.Fatal(err)
80		}
81		if v.Revision != 2 || string(v.Desired) != `{"a":2}` {
82			t.Fatalf("restored view: %+v", v)
83		}
84		// Get 与 Audit 保留已有内容和顺序
85		recs, err := s.Audit("dev-1")
86		if err != nil || len(recs) != 2 {
87			t.Fatalf("restored audit: %v %v", recs, err)
88		}
89		if recs[0].Revision != 1 || recs[1].Revision != 2 ||
90			recs[0].Operator != "alice" || recs[1].Operator != "bob" {
91			t.Fatalf("audit content/order changed: %+v", recs)
92		}
93	}
94	
95	// 从未修改过期望配置的设备：修订号 0、空审计、空对象期望配置。
96	// 设备已经上报其他配置或版本不影响这一判断。
97	func TestRestoreZeroRevisionAccepted(t *testing.T) {
98		dir, _ := writeFixStore(t, fixStore{Format: 1, Devices: map[string]fixState{
99			"dev-1": {
100				Version:        "1.1",
101				Online:         true,
102				Revision:       0,
103				Desired:        json.RawMessage(`{}`),
104				Reported:       json.RawMessage(`{"cpu":80}`),
