107				DiffSince:      map[string]string{"/cpu": "2026-10-02T12:00:00Z"},
108			},
109		}})
110		s, err := Open(dir)
111		if err != nil {
112			t.Fatalf("reported config must not affect revision-zero device: %v", err)
113		}
114		defer s.Close()
115		v, _ := s.Get("dev-1")
116		if v.Revision != 0 || string(v.Desired) != "{}" || v.LastSeq != 7 || v.Version != "1.1" {
117			t.Fatalf("restored view: %+v", v)
118		}
119		if recs, _ := s.Audit("dev-1"); len(recs) != 0 {
120			t.Fatalf("unexpected audit: %+v", recs)
121		}
122	}
123	
124	// 配置比较沿用 JSON 语义：空白与对象字段顺序无关，1 与 1.0 相等；
125	// 记录只按修订号衔接，不要求操作时间严格递增。
126	func TestRestoreAuditChainSemanticEquality(t *testing.T) {
127		dir, _ := writeFixStore(t, fixStore{Format: 1, Devices: map[string]fixState{
128			"dev-1": {
