138					{Operator: "bob", Time: "2026-10-02T12:00:00Z", Revision: 2, Before: json.RawMessage(`{ "a" : 1 }`), After: json.RawMessage(`{"a":1.0}`)},
139				},
140			},
141		}})
142		s, err := Open(dir)
143		if err != nil {
144			t.Fatalf("semantic-equal chain with non-monotonic times must open: %v", err)
145		}
