160			t.Fatal(err)
161		}
162		if err := s.Close(); err != nil {
163			t.Fatal(err)
164		}
165		s2, err := Open(dir)
166		if err != nil {
167			t.Fatalf("equal-config revisions must reopen: %v", err)
168		}
169		defer s2.Close()
170		recs, _ := s2.Audit("dev-1")
171		if len(recs) != 3 {
172			t.Fatalf("audit: %+v", recs)
173		}
