180	// 历史中交替出现单设备修改与批量修改：较早的批量请求只对应当时那条审计，
181	// 重开后链式校验与批量查询都仍以各自修订号为准。
182	func TestRestoreInterleavedBatchAndSingle(t *testing.T) {
183		s, dir := openTemp(t)
184		mustRegister(t, s, "dev-1", "1.0")
185		mustBatch(t, s, "req-1", "alice", base, []BatchDevice{
186			{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`{"a":1}`)},
187		})
188		if _, err := s.UpdateDesired("dev-1", "bob", base.Add(time.Hour), 1, json.RawMessage(`{"a":2}`)); err != nil {
189			t.Fatal(err)
190		}
191		mustBatch(t, s, "req-2", "alice", base.Add(2*time.Hour), []BatchDevice{
192			{DeviceID: "dev-1", Revision: 2, Config: json.RawMessage(`{"a":3}`)},
193		})
194		if err := s.Close(); err != nil {
195			t.Fatal(err)
196		}
197		s2, err := Open(dir)
198		if err != nil {
199			t.Fatalf("interleaved history must reopen: %v", err)
200		}
201		defer s2.Close()
202		recs, _ := s2.Audit("dev-1")
203		if len(recs) != 3 || recs[0].RequestID != "req-1" || recs[1].RequestID != "" || recs[2].RequestID != "req-2" {
204			t.Fatalf("audit order/markers: %+v", recs)
205		}
206		// 较早批量请求仍记录当时的新修订号 1，不能拿设备最新配置比较
207		rec, err := s2.GetBatchRequest("req-1")
208		if err != nil {
209			t.Fatal(err)
210		}
211		if rec.Revisions["dev-1"] != 1 {
212			t.Fatalf("old batch record: %+v", rec.Revisions)
213		}
214		v, _ := s2.Get("dev-1")
215		if v.Revision != 3 || string(v.Desired) != `{"a":3}` {
216			t.Fatalf("latest view: %+v", v)
217		}
218	}
219	
220	// 任一设备历史缺失、断开或与当前期望不符都拒绝打开整个存储，
221	// 且原文件内容保持不变。
222	func TestRestoreAuditChainCorruptRefused(t *testing.T) {
223		op := "op"
224		t1 := "2026-10-02T12:00:00Z"
225		t2 := "2026-10-02T12:01:00Z"
226		empty := json.RawMessage(`{}`)
227		a1 := json.RawMessage(`{"a":1}`)
228		a2 := json.RawMessage(`{"a":2}`)
229		a3 := json.RawMessage(`{"a":3}`)
230		a9 := json.RawMessage(`{"a":9}`)
231		x1 := json.RawMessage(`{"x":1}`)
232	
233		cases := map[string]func(fixStore){
234			// 删掉修订号 1 的审计，只留修订号 2 与当前影子
235			"first audit missing": func(doc fixStore) {
236				d := doc.Devices["dev-1"]
237				d.Audit = d.Audit[1:]
238				doc.Devices["dev-1"] = d
239			},
240			// 修订号断开：1 之后直接是 3
241			"revision gap": func(doc fixStore) {
242				d := doc.Devices["dev-1"]
243				d.Audit[1].Revision = 3
244				doc.Devices["dev-1"] = d
245			},
246			// 审计未从修订号 1 开始（条数与修订号相符，但首条修订号为 2）
247			"audit not from one": func(doc fixStore) {
248				d := doc.Devices["dev-1"]
249				d.Audit = []fixAudit{
250					{Operator: op, Time: t1, Revision: 2, Before: empty, After: a1},
251					{Operator: op, Time: t2, Revision: 3, Before: a1, After: a2},
252				}
253				doc.Devices["dev-1"] = d
254			},
255			// 首条修改前不是登记时的空对象
256			"first before not empty": func(doc fixStore) {
257				d := doc.Devices["dev-1"]
258				d.Revision = 1
259				d.Desired = a1
260				d.Audit = []fixAudit{
261					{Operator: op, Time: t1, Revision: 1, Before: x1, After: a1},
262				}
263				doc.Devices["dev-1"] = d
264			},
265			// 相邻记录断开：第二条修改前不等于第一条修改后
266			"chain broken": func(doc fixStore) {
267				d := doc.Devices["dev-1"]
268				d.Audit[1].Before = a9
269				doc.Devices["dev-1"] = d
270			},
271			// 末条修改后与当前期望配置不同
272			"last after mismatches desired": func(doc fixStore) {
273				d := doc.Devices["dev-1"]
274				d.Desired = a3
275				doc.Devices["dev-1"] = d
276			},
277			// 当前修订号大于审计条数：历史解释不了现状
278			"revision beyond audit": func(doc fixStore) {
279				d := doc.Devices["dev-1"]
280				d.Revision = 3
281				doc.Devices["dev-1"] = d
282			},
283			// 有审计却声称修订号 0
284			"audit with revision zero": func(doc fixStore) {
285				d := doc.Devices["dev-1"]
286				d.Revision = 0
287				d.Desired = empty
288				doc.Devices["dev-1"] = d
289			},
290			// 修订号 0、无审计，但期望配置不是空对象
291			"desired not empty at revision zero": func(doc fixStore) {
292				d := doc.Devices["dev-1"]
293				d.Revision = 0
294				d.Desired = a1
295				d.Audit = nil
296				doc.Devices["dev-1"] = d
297			},
298		}
299		for name, mutate := range cases {
300			t.Run(name, func(t *testing.T) {
301				doc := twoAuditDoc()
302				mutate(doc)
303				dir, original := writeFixStore(t, doc)
304				s, err := Open(dir)
305				if err == nil {
306					s.Close()
307					t.Fatalf("expected ErrCorruptStorage")
308				}
309				if !errors.Is(err, ErrCorruptStorage) {
310					t.Fatalf("error must wrap ErrCorruptStorage: %v", err)
311				}
312				// 原文件内容保持不变
313				data, rerr := os.ReadFile(filepath.Join(dir, storeFileName))
314				if rerr != nil {
315					t.Fatal(rerr)
316				}
317				if string(data) != string(original) {
318					t.Fatalf("corrupt file modified on rejected open")
319				}
320			})
321		}
322	}
323	
324	// 一台设备损坏即拒绝打开整个存储，其他正常设备也不可用。
325	func TestRestoreOneDeviceCorruptRejectsAll(t *testing.T) {
326		doc := twoAuditDoc()
327		doc.Devices["good"] = fixState{
328			Version:  "1.0",
329			Desired:  json.RawMessage(`{}`),
330			Reported: json.RawMessage(`{}`),
331		}
332		bad := doc.Devices["dev-1"]
333		bad.Audit = []fixAudit{
334			{Operator: "op", Time: "2026-10-02T12:00:00Z", Revision: 1, Before: json.RawMessage(`{}`), After: json.RawMessage(`{"a":2}`)},
335		}
336		doc.Devices["bad"] = bad
337		delete(doc.Devices, "dev-1")
338		dir, _ := writeFixStore(t, doc)
339		if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
340			t.Fatalf("whole store must be refused when one device history mismatches: %v", err)
341		}
342	}
