218	// TestResultHistoryLegitStatesReopen 校验各种合法进度重开后历史与结果保持对应，
219	// 不凭空要求未完成或未执行阶段产生结果。
220	func TestResultHistoryLegitStatesReopen(t *testing.T) {
221		t.Run("download success awaiting install", func(t *testing.T) {
222			_, dir, spec := setupReady(t)
223			s, err := Open(dir)
224			if err != nil {
225				t.Fatalf("ready state must open: %v", err)
226			}
227			defer s.Close()
228			cv, err := s.GetCampaign(spec.ID)
229			if err != nil {
230				t.Fatal(err)
231			}
232			d := findDevice(cv, "d1")
233			if d.Status != DeviceReady || len(cv.Results) != 1 || cv.Results[0].Stage != StageDownload {
234				t.Fatalf("restored ready view: status=%s results=%+v", d.Status, cv.Results)
235			}
236			// 已接受结果的重复提交沿用现有幂等判断，不新增历史。
237			if err := s.SubmitResult(OperationResult{
238				CampaignID: spec.ID, DeviceID: "d1",
239				OperationID: cv.Results[0].OperationID,
240				At:          cv.Results[0].At, Success: true,
241			}); err != nil {
242				t.Fatalf("duplicate replay: %v", err)
243			}
244			if cv2, _ := s.GetCampaign(spec.ID); len(cv2.Results) != 1 {
245				t.Fatalf("replay added history: %+v", cv2.Results)
246			}
247		})
