249		t.Run("claim-time download failure kept", func(t *testing.T) {
250			// 首次领取下载时版本已不兼容：下载失败是已有结果，必须保留历史。
251			s := setupUpgrade(t, "d1")
252			spec := upSpec()
253			spec.Devices = []string{"d1"}
254			createCampaign(t, s, spec)
255			if err := s.Report("d1", 1, upBase.Add(-time.Minute), "v3", json.RawMessage(`{}`)); err != nil {
256				t.Fatal(err)
257			}
258			if _, err := s.Claim(spec.ID, "d1", upBase); !errors.Is(err, ErrIncompatibleVersion) {
259				t.Fatalf("want incompatible version, got %v", err)
260			}
261			cv := mustGetCampaign(s, spec.ID)
262			if len(cv.Results) != 1 || cv.Results[0].Success {
263				t.Fatalf("download failure history: %+v", cv.Results)
264			}
265			dir := s.dir
266			s.Close()
267			s2, err := Open(dir)
268			if err != nil {
269				t.Fatalf("claim-time failure must reopen: %v", err)
270			}
271			defer s2.Close()
272			cv2 := mustGetCampaign(s2, spec.ID)
273			if findDevice(cv2, "d1").Status != DeviceFailed || len(cv2.Results) != 1 {
274				t.Fatalf("restored failure view: %+v", cv2)
275			}
276			// 失败原因矛盾也必须被拒绝。
277			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
278				resultDocs(doc, "cmp-1")[0]["reason"] = "other reason"
279			})
280			assertReopenCorrupt(t, dir, original)
281		})
