309		t.Run("later batch skipped has no history", func(t *testing.T) {
310			// 前一批失败后，后续批次未执行：不为其凭空产生结果历史。
311			s := setupUpgrade(t, "d1", "d2")
312			spec := upSpec()
313			spec.BatchSize = 1
314			spec.Devices = []string{"d1", "d2"}
