355					t.Fatalf("claim rollback: %v", err)
356				}
357				if err := s.AdvanceCampaign(spec.ID, spec.Deadline); err != nil {
358					t.Fatal(err)
359				}
360			}, DeviceRollbackTimeout},
361		} {
362			t.Run(tc.name, func(t *testing.T) {
363				s, dir, spec, _ := setupInstallFailure(t, true)
364				tc.advance(s, spec)
365				if err := s.Close(); err != nil {
366					t.Fatal(err)
367				}
368				s2, err := Open(dir)
369				if err != nil {
370					t.Fatalf("%s must reopen: %v", tc.name, err)
371				}
372				defer s2.Close()
373				cv2 := mustGetCampaign(s2, spec.ID)
374				d := findDevice(cv2, "d1")
375				if d.Status != tc.want {
376					t.Fatalf("status: want %s got %s", tc.want, d.Status)
377				}
378				// 只有下载成功、安装失败两条记录；回滚尚无结果。
379				if len(cv2.Results) != 2 {
380					t.Fatalf("history: %+v", cv2.Results)
381				}
382				if cv2.Results[1].Success || cv2.Results[1].Reason != "install boom" {
383					t.Fatalf("install failure not preserved: %+v", cv2.Results[1])
384				}
385			})
386		}
