388		t.Run("rollback failure kept", func(t *testing.T) {
389			s, _, spec, rbOp := setupInstallFailure(t, true)
390			if _, err := s.Claim(spec.ID, "d1", upBase.Add(4*time.Minute)); err != nil {
391				t.Fatal(err)
392			}
393			if err := s.SubmitResult(OperationResult{
394				CampaignID: spec.ID, DeviceID: "d1", OperationID: rbOp.ID,
395				At: upBase.Add(5 * time.Minute), Success: false, Reason: "rollback boom",
396			}); err != nil {
397				t.Fatalf("rollback failure: %v", err)
398			}
399			dir := s.dir
400			s.Close()
401			s2, err := Open(dir)
402			if err != nil {
403				t.Fatalf("rollback failed state must reopen: %v", err)
404			}
405			defer s2.Close()
406			cv := mustGetCampaign(s2, spec.ID)
407			if findDevice(cv, "d1").Status != DeviceRollbackFailed || len(cv.Results) != 3 {
408				t.Fatalf("view: %+v", cv.Results)
409			}
410			// 缺少回滚失败记录即损坏。
411			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
412				rs := resultDocs(doc, "cmp-1")
413				campaignDoc(doc, "cmp-1")["results"] = []any{rs[0], rs[1]}
414			})
415			assertReopenCorrupt(t, dir, original)
416		})
417	
418		t.Run("rollback success version correspondence", func(t *testing.T) {
419			s, _, spec, rbOp := setupInstallFailure(t, true)
420			if _, err := s.Claim(spec.ID, "d1", upBase.Add(4*time.Minute)); err != nil {
421				t.Fatal(err)
422			}
423			if err := s.SubmitResult(OperationResult{
424				CampaignID: spec.ID, DeviceID: "d1", OperationID: rbOp.ID,
425				At: upBase.Add(5 * time.Minute), Success: true,
426				Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
427			}); err != nil {
428				t.Fatalf("rollback success: %v", err)
429			}
430			dir := s.dir
431			s.Close()
432			// 设备后来通过普通上报改变当前版本，不能否定此前合法的回滚历史。
433			s2, err := Open(dir)
434			if err != nil {
435				t.Fatalf("rollback success state must reopen: %v", err)
436			}
437			if err := s2.Report("d1", 3, upBase.Add(90*time.Minute), "v3", json.RawMessage(`{}`)); err != nil {
438				t.Fatal(err)
439			}
440			s2.Close()
441			s3, err := Open(dir)
442			if err != nil {
443				t.Fatalf("report after rollback must not invalidate history: %v", err)
444			}
445			defer s3.Close()
446			cv := mustGetCampaign(s3, spec.ID)
447			d := findDevice(cv, "d1")
448			if d.Status != DeviceRollbackSucceeded || len(cv.Results) != 3 {
449				t.Fatalf("view: %+v", cv.Results)
450			}
451			if cv.Results[2].Version != "v1" {
452				t.Fatalf("rollback history version: %+v", cv.Results[2])
453			}
454			// 回滚记录的版本与当次接受版本矛盾即损坏。
455			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
456				resultDocs(doc, "cmp-1")[2]["version"] = "v3"
457			})
458			assertReopenCorrupt(t, dir, original)
459		})
460	
461		t.Run("install success then version drifts", func(t *testing.T) {
462			// 普通上报改变当前版本，不否定此前合法的安装历史（记录版本仍为目标版本）。
463			_, dir, spec := setupSucceeded(t)
464			s, err := Open(dir)
465			if err != nil {
466				t.Fatal(err)
467			}
468			if err := s.Report("d1", 3, upBase.Add(90*time.Minute), "v3", json.RawMessage(`{}`)); err != nil {
469				t.Fatal(err)
470			}
471			s.Close()
472			s2, err := Open(dir)
473			if err != nil {
474				t.Fatalf("version drift after install must reopen: %v", err)
475			}
476			defer s2.Close()
477			cv := mustGetCampaign(s2, spec.ID)
478			if findDevice(cv, "d1").Status != DeviceSucceeded || cv.Results[1].Version != "v2" {
479				t.Fatalf("view: %+v", cv.Results)
480			}
481		})
482	}
483	
484	// setupInstallFailure 构造下载成功、安装失败已接受（等待回滚）的状态。
485	func setupInstallFailure(t *testing.T, rollback bool) (*Store, string, CampaignSpec, *Operation) {
486		t.Helper()
487		s := setupUpgrade(t, "d1")
488		spec := upSpec()
489		spec.Devices = []string{"d1"}
490		spec.RollbackOnFailure = rollback
491		createCampaign(t, s, spec)
492		bringOnline(t, s, "d1")
493		dl, err := s.Claim(spec.ID, "d1", upBase)
494		if err != nil {
495			t.Fatalf("claim download: %v", err)
496		}
497		if err := s.SubmitResult(OperationResult{
498			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
499			At: upBase.Add(time.Minute), Success: true,
500		}); err != nil {
501			t.Fatalf("download: %v", err)
502		}
503		in, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
504		if err != nil {
505			t.Fatalf("claim install: %v", err)
506		}
507		if err := s.SubmitResult(OperationResult{
508			CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
509			At: upBase.Add(3 * time.Minute), Success: false, Reason: "install boom",
510		}); err != nil {
511			t.Fatalf("install failure: %v", err)
512		}
513		rbID := findDevice(mustGetCampaign(s, spec.ID), "d1").RollbackID
514		return s, s.dir, spec, &Operation{ID: rbID}
515	}
516	
517	// TestResultHistorySuccessWithExtraReasonReopen 提交成功结果时附带了非空原因
518	// （提交路径不拒绝）：原因只存在操作结果上、不进入历史，重开不得误判为矛盾。
519	func TestResultHistorySuccessWithExtraReasonReopen(t *testing.T) {
520		s := setupUpgrade(t, "d1")
521		spec := upSpec()
522		spec.Devices = []string{"d1"}
523		createCampaign(t, s, spec)
524		bringOnline(t, s, "d1")
525		dl, err := s.Claim(spec.ID, "d1", upBase)
526		if err != nil {
527			t.Fatal(err)
528		}
529		// 成功结果携带原因：被接受，历史记录不含原因。
530		if err := s.SubmitResult(OperationResult{
531			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
532			At: upBase.Add(time.Minute), Success: true, Reason: "informational note",
533		}); err != nil {
534			t.Fatalf("success result with reason must be accepted: %v", err)
535		}
536		dir := s.dir
537		s.Close()
538		s2, err := Open(dir)
539		if err != nil {
540			t.Fatalf("success op result carrying a reason must not break history check: %v", err)
541		}
542		defer s2.Close()
543		cv := mustGetCampaign(s2, spec.ID)
544		if findDevice(cv, "d1").Status != DeviceReady || len(cv.Results) != 1 || cv.Results[0].Reason != "" {
545			t.Fatalf("view: %+v", cv.Results)
546		}
547	}
548	
549	// TestResultHistoryTimezoneEqualInstant 历史时间与操作结果时间是同一时刻、
550	// 仅时区表示不同（Z vs +08:00）时不得判为冲突。
551	func TestResultHistoryTimezoneEqualInstant(t *testing.T) {
552		_, dir, _ := setupReady(t)
553		// 下载结果接受于 12:01:00Z，改写为 +08:00 表示的同一时刻 20:01:00+08:00。
554		rewriteStoreBytes(t, dir, func(doc map[string]any) {
555			resultDocs(doc, "cmp-1")[0]["at"] = "2026-10-02T20:01:00+08:00"
556		})
557		s, err := Open(dir)
558		if err != nil {
559			t.Fatalf("same instant in different zone must open: %v", err)
560		}
561		defer s.Close()
562		cv := mustGetCampaign(s, "cmp-1")
563		want := upBase.Add(time.Minute)
564		if !cv.Results[0].At.Equal(want) {
565			t.Fatalf("restored time %v not equal to %v", cv.Results[0].At, want)
566		}
567	}
568	
569	// TestResultHistoryPreservesOrderAndContent 合法数据按原样打开：
570	// 设备进度、结果内容与接受顺序不变。
571	func TestResultHistoryPreservesOrderAndContent(t *testing.T) {
572		s := setupUpgrade(t, "d1", "d2")
573		spec := upSpec()
574		spec.BatchSize = 2
575		spec.Devices = []string{"d1", "d2"}
576		createCampaign(t, s, spec)
577		bringOnline(t, s, "d1")
578		bringOnline(t, s, "d2")
579		finishDevice(t, s, spec, "d1", upBase)
580		finishDevice(t, s, spec, "d2", upBase.Add(10*time.Minute))
581		cv0 := mustGetCampaign(s, spec.ID)
582		dir := s.dir
583		s.Close()
584	
585		s2, err := Open(dir)
586		if err != nil {
587			t.Fatalf("valid history must reopen: %v", err)
588		}
589		defer s2.Close()
590		cv := mustGetCampaign(s2, spec.ID)
591		if cv.Status != CampaignSucceeded || len(cv.Results) != len(cv0.Results) {
592			t.Fatalf("restored campaign: status=%s results=%+v", cv.Status, cv.Results)
593		}
594		for i := range cv0.Results {
595			a, b := cv0.Results[i], cv.Results[i]
596			if a != b {
597				t.Fatalf("result %d changed: %+v vs %+v", i, a, b)
598			}
599		}
