236	// TestRestoreUnfinishedDownloadResumes 保护正常的未完成下载在重开后仍能恢复使用：
237	// 尚未领取下载的设备保留未领取标记与原操作标识；已领取下载的设备保留原操作标识
238	// 和已领取标记，截止前再次领取仍返回同一下载标识，后续提交结果沿用现有规则。
239	// 设备离线、维护窗口已经结束或普通上报改变了当前版本，都不能单凭这些情况认定
240	// 进度损坏，也不能自动补上下载结果。
241	func TestRestoreUnfinishedDownloadResumes(t *testing.T) {
242		// pending 原样重开（在线、窗口内）：未领取标记与操作标识保留，
243		// 领取后状态进入 downloading，提交下载成功后进入 ready。
244		t.Run("pending reopens and claims", func(t *testing.T) {
245			s, spec := buildPendingOpen(t)
246			wantWork, err := s.GetDeviceWork("d1")
247			if err != nil {
248				t.Fatal(err)
249			}
250			dir := closeStore(t, s)
251	
252			s2, err := Open(dir)
253			if err != nil {
254				t.Fatalf("pending store must reopen: %v", err)
255			}
256			defer s2.Close()
257			cv := mustGetCampaign(s2, spec.ID)
258			if cv.Ended || findDevice(cv, "d1").Status != DevicePending ||
259				findDevice(cv, "d1").Phase != StageDownload {
260				t.Fatalf("pending progress must be preserved: %+v", cv)
261			}
262			if len(cv.Results) != 0 {
263				t.Fatalf("no download result may be fabricated: %+v", cv.Results)
264			}
265			w, err := s2.GetDeviceWork("d1")
266			if err != nil {
267				t.Fatal(err)
268			}
269			if w.CampaignID != spec.ID || w.Pending == nil ||
270				w.Pending.Kind != StageDownload || w.PendingClaimed ||
271				w.Pending.ID != wantWork.Pending.ID {
272				t.Fatalf("unclaimed download todo lost: %+v want %+v", w, wantWork)
273			}
274			dl, err := s2.Claim(spec.ID, "d1", upBase.Add(time.Minute))
275			if err != nil || dl == nil || dl.Kind != StageDownload || dl.ID != wantWork.Pending.ID {
276				t.Fatalf("claim restored download: %v %+v", err, dl)
277			}
278			if err := s2.SubmitResult(OperationResult{
279				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
280				At: upBase.Add(2 * time.Minute), Success: true,
281			}); err != nil {
282				t.Fatalf("submit download after reopen: %v", err)
283			}
284			cv = mustGetCampaign(s2, spec.ID)
285			if cv.Ended || findDevice(cv, "d1").Status != DeviceReady ||
286				findDevice(cv, "d1").Phase != StageInstall {
287				t.Fatalf("download should complete into ready: %+v", cv)
288			}
289		})
290	
291		// pending：设备离线、维护窗口已结束后重开，仍保留未领取的下载待办；
292		// 窗口外领取仍返回空操作，不补造任何结果。
293		t.Run("pending survives offline and ended window", func(t *testing.T) {
294			s, spec := buildPendingOpen(t)
295			// 离线并把时间推进到维护窗口结束之后、截止之前。
296			if err := s.SetOffline("d1"); err != nil {
297				t.Fatal(err)
298			}
299			if err := s.AdvanceCampaign(spec.ID, upBase.Add(90*time.Minute)); err != nil {
300				t.Fatal(err)
301			}
302			wantWork, err := s.GetDeviceWork("d1")
303			if err != nil {
304				t.Fatal(err)
305			}
306			dir := closeStore(t, s)
307	
308			s2, err := Open(dir)
309			if err != nil {
310				t.Fatalf("pending device offline past window must reopen: %v", err)
311			}
312			defer s2.Close()
313	
314			cv := mustGetCampaign(s2, spec.ID)
315			if cv.Ended || findDevice(cv, "d1").Status != DevicePending ||
316				findDevice(cv, "d1").Phase != StageDownload {
317				t.Fatalf("pending progress must be preserved: %+v", cv)
318			}
319			if len(cv.Results) != 0 {
320				t.Fatalf("no download result may be fabricated: %+v", cv.Results)
321			}
322			w, err := s2.GetDeviceWork("d1")
323			if err != nil {
324				t.Fatal(err)
325			}
326			if w.CampaignID != spec.ID || w.Pending == nil ||
327				w.Pending.Kind != StageDownload || w.PendingClaimed ||
328				w.Pending.ID != wantWork.Pending.ID {
329				t.Fatalf("unclaimed download todo lost: %+v want %+v", w, wantWork)
330			}
331			// 窗口已结束：即使重新上线，未领取的下载仍领不到（正常等待，不是错误），
332			// 状态与待办保持不变。
333			bringOnline(t, s2, "d1")
334			op, err := s2.Claim(spec.ID, "d1", upBase.Add(91*time.Minute))
335			if err != nil {
336				t.Fatalf("claim outside window must be a no-op, not error: %v", err)
337			}
338			if op != nil {
339				t.Fatalf("unclaimed download must not be dispatched past window: %+v", op)
340			}
341			w2, _ := s2.GetDeviceWork("d1")
342			if w2.Pending == nil || w2.PendingClaimed || w2.Pending.ID != w.Pending.ID {
343				t.Fatalf("pending download changed after out-of-window claim: %+v", w2)
344			}
345			if findDevice(mustGetCampaign(s2, spec.ID), "d1").Status != DevicePending {
346				t.Fatalf("pending status must remain after out-of-window claim")
347			}
348		})
349	
350		// downloading：原操作标识与已领取标记保留；截止前再次领取返回同一下载标识，
351		// 已领取操作可在窗口外、截止前按现有规则提交下载结果。
352		t.Run("downloading reopens and keeps claimed operation", func(t *testing.T) {
353			s, spec, dl := buildDownloadingOpen(t)
354			wantWork, _ := s.GetDeviceWork("d1")
355			dir := closeStore(t, s)
356	
357			s2, err := Open(dir)
358			if err != nil {
359				t.Fatalf("downloading store must reopen: %v", err)
360			}
361			defer s2.Close()
362			cv := mustGetCampaign(s2, spec.ID)
363			if cv.Ended || findDevice(cv, "d1").Status != DeviceDownloading ||
364				findDevice(cv, "d1").Phase != StageDownload {
365				t.Fatalf("downloading progress must be preserved: %+v", cv)
366			}
367			if len(cv.Results) != 0 {
368				t.Fatalf("no download result may be fabricated: %+v", cv.Results)
369			}
370			w, err := s2.GetDeviceWork("d1")
371			if err != nil {
372				t.Fatal(err)
373			}
374			if w.Pending == nil || w.Pending.Kind != StageDownload || !w.PendingClaimed ||
375				w.Pending.ID != dl.ID || w.Pending.ID != wantWork.Pending.ID {
376				t.Fatalf("claimed download not restored: %+v want %+v", w, wantWork)
377			}
378			// 截止前再次领取（即使在窗口外）仍返回同一下载标识。
379			again, err := s2.Claim(spec.ID, "d1", upBase.Add(75*time.Minute))
380			if err != nil || again == nil || again.ID != dl.ID {
381				t.Fatalf("re-claim must return same download id: %v %+v", err, again)
382			}
383			// 已领取操作可在窗口外、截止前提交结果：沿用原标识与现有规则。
384			if err := s2.SubmitResult(OperationResult{
385				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
386				At: upBase.Add(76 * time.Minute), Success: true,
387			}); err != nil {
388				t.Fatalf("submit download result after reopen: %v", err)
389			}
390			cv = mustGetCampaign(s2, spec.ID)
391			if cv.Ended || findDevice(cv, "d1").Status != DeviceReady ||
392				findDevice(cv, "d1").Phase != StageInstall {
393				t.Fatalf("download should complete into ready: %+v", cv)
394			}
395			if len(cv.Results) != 1 || cv.Results[0].Stage != StageDownload ||
396				cv.Results[0].OperationID != dl.ID {
397				t.Fatalf("download result history: %+v", cv.Results)
398			}
399		})
400	
401		// 已领取下载的设备离线重开：离线不影响已领取待办的恢复。
402		t.Run("downloading reopens while offline", func(t *testing.T) {
403			s, spec, dl := buildDownloadingOpen(t)
404			if err := s.SetOffline("d1"); err != nil {
405				t.Fatal(err)
406			}
407			dir := closeStore(t, s)
408			s2, err := Open(dir)
409			if err != nil {
410				t.Fatalf("offline downloading store must reopen: %v", err)
411			}
412			defer s2.Close()
413			if sh, _ := s2.Get("d1"); sh.Online {
414				t.Fatalf("offline state must be preserved")
415			}
416			w, err := s2.GetDeviceWork("d1")
417			if err != nil {
418				t.Fatal(err)
419			}
420			if w.Pending == nil || w.Pending.Kind != StageDownload || !w.PendingClaimed ||
421				w.Pending.ID != dl.ID {
422				t.Fatalf("claimed download todo lost while offline: %+v", w)
423			}
424			if findDevice(mustGetCampaign(s2, spec.ID), "d1").Status != DeviceDownloading {
425				t.Fatalf("downloading status lost")
426			}
427		})
428	
429		// 尚未领取下载没有领取时间、尚无下载结果没有结果时间：正常缺省记录
430		// 必须原样打开，Open 不得改写文件补这些时间。
431		t.Run("missing claim and result times are normal", func(t *testing.T) {
432			// pending：下载从未领取，没有领取时间与结果时间。
433			_, dir, spec := setupPending(t)
434			path := filepath.Join(dir, storeFileName)
435			data, err := os.ReadFile(path)
436			if err != nil {
437				t.Fatal(err)
438			}
439			s2, err := Open(dir)
440			if err != nil {
441				t.Fatalf("pending store with default download times must reopen: %v", err)
442			}
443			if findDevice(mustGetCampaign(s2, spec.ID), "d1").Status != DevicePending {
444				t.Fatalf("pending status lost")
445			}
446			s2.Close()
447			data2, err := os.ReadFile(path)
448			if err != nil {
449				t.Fatal(err)
450			}
451			if string(data2) != string(data) {
452				t.Fatalf("open must not fabricate missing times")
453			}
454	
455			// downloading：下载已领取但尚无结果，没有结果时间。
456			_, dir2, spec2 := setupDownloading(t)
457			path2 := filepath.Join(dir2, storeFileName)
458			data, err = os.ReadFile(path2)
459			if err != nil {
460				t.Fatal(err)
461			}
462			s3, err := Open(dir2)
463			if err != nil {
464				t.Fatalf("downloading store without result time must reopen: %v", err)
465			}
466			if findDevice(mustGetCampaign(s3, spec2.ID), "d1").Status != DeviceDownloading {
467				t.Fatalf("downloading status lost")
468			}
469			s3.Close()
470			data2, err = os.ReadFile(path2)
471			if err != nil {
472				t.Fatal(err)
473			}
474			if string(data2) != string(data) {
475				t.Fatalf("open must not fabricate missing times")
476			}
477		})
478	}
